mapper.select:
SELECT COALESCE(SUM(pr.amount), 0)
FROM payment_record pr
WHERE pr.semester_id = #{semesterId}

SELECT pr.semester_id AS semesterId, se.semester_name AS semesterName, COALESCE(SUM(pr.amount), 0) AS totalAmount FROM payment_record pr LEFT JOIN semester se ON pr.semester_id = se.id WHERE pr.semester_id IN
#{id}
GROUP BY pr.semester_id, se.semester_name ORDER BY pr.semester_id
